    $st_menu = $pdo->prepare("INSERT INTO `menu_diet` (`id`, `nama_menu`, `waktu_makan`, `kalori`, `berat_gram`, `takaran_saji`, `harga`, `vegetarian`, `deskripsi`) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)");
    $st_komp = $pdo->prepare("INSERT INTO `menu_komponen` (`menu_id`, `nama_komponen`, `takaran`, `berat_gram`, `kondisi`, `kalori_per_100g`, `kalori_komponen`, `sumber`) VALUES (?, ?, ?, ?, ?, ?, ?, ?)");

    $count_m = 0;
    $count_k = 0;
    $sample_checks = [];

    $pdo->beginTransaction();
    foreach ($dataset as $mid => $m) {
        $mid = (int)$mid;
        $kalori = (int)round($m['total_kalori']);
        $berat  = (int)round($m['total_gram']);
        $st_menu->execute([
            $mid,
            $m['nama'],
            $m['waktu_makan'],
            $kalori,
            $berat,
            $m['takaran_saji'],
            $m['harga'],
            $m['vegetarian'],
            $m['deskripsi']
        ]);
        $count_m++;

        foreach ($m['komponen'] as $k) {
            $st_komp->execute([
                $mid,
                $k['komponen'],
                $k['takaran'],
                $k['gram'],
                $k['kondisi'],
                $k['kkal_per_100g'],
                $k['kkal_komponen'],
                $k['sumber']
            ]);
            $count_k++;
        }

        if (in_array($m['nama'], ['Telur rebus dan buah potong', 'Bubur kacang hijau', 'Lontong isi sayur', 'Soto ayam', 'Batagor', 'Nasi uduk tempe'])) {
            $sample_checks[] = [
                'id' => $mid,
                'nama' => $m['nama'],
                'takaran' => $m['takaran_saji'],
                'kalori' => $kalori,
                'berat' => $berat
            ];
        }
    }

    // 4. Petakan Kategori BMI
    echo '<div class="step info">4. Memetakan rekomendasi kategori BMI...</div>';
    $pdo->exec("INSERT INTO menu_kategori (menu_id, kategori_id)
    SELECT id, 1 FROM menu_diet WHERE (waktu_makan = 'camilan' AND kalori >= 121) OR (waktu_makan = 'pagi' AND kalori >= 281) OR (waktu_makan = 'siang' AND kalori >= 421) OR (waktu_makan = 'malam' AND kalori >= 261);");

    $pdo->exec("INSERT INTO menu_kategori (menu_id, kategori_id)
    SELECT id, 2 FROM menu_diet;");

    $pdo->exec("INSERT INTO menu_kategori (menu_id, kategori_id)
    SELECT id, 3 FROM menu_diet WHERE (waktu_makan = 'camilan' AND kalori <= 180) OR (waktu_makan = 'pagi' AND kalori <= 420) OR (waktu_makan = 'siang' AND kalori <= 550) OR (waktu_makan = 'malam' AND kalori <= 340);");

    $pdo->exec("INSERT INTO menu_kategori (menu_id, kategori_id)
    SELECT id, 4 FROM menu_diet WHERE (waktu_makan = 'camilan' AND kalori <= 120) OR (waktu_makan = 'pagi' AND kalori <= 280) OR (waktu_makan = 'siang' AND kalori <= 420) OR (waktu_makan = 'malam' AND kalori <= 260);");

    $pdo->commit();
    $pdo->exec("SET FOREIGN_KEY_CHECKS = 1");

    echo '<div class="step sukses"><strong>BERHASIL TOTAL!</strong><br>&bull; ' . $count_m . ' menu makanan berhasil dibuat bersih 100%.<br>&bull; ' . $count_k . ' rincian komponen porsi berhasil diinput ke tabel menu_komponen.<br>&bull; Seluruh pemetaan BMI telah terhubung sempurna.</div>';

    echo '<h3>Verifikasi Menu (Sudah Selaras 100%):</h3>';
    echo '<table class="sample-table"><thead><tr><th>ID</th><th>Nama Menu</th><th>Takaran 1 Porsi</th><th>Kalori</th></tr></thead><tbody>';
    foreach ($sample_checks as $sc) {
        echo '<tr><td>' . $sc['id'] . '</td><td><strong>' . htmlspecialchars($sc['nama']) . '</strong></td><td>' . htmlspecialchars($sc['takaran']) . '</td><td>' . $sc['kalori'] . ' kkal</td></tr>';
    }
    echo '</tbody></table>';

    echo '<br><a href="menu.php" class="btn">Lihat Halaman Menu</a> ';
    echo '<a href="admin/makanan.php" class="btn" style="background:#475569;">Buka Panel Admin</a>';

} catch (Exception $e) {
    if ($pdo->inTransaction()) $pdo->rollBack();
    echo '<div class="step error"><strong>Gagal:</strong> ' . htmlspecialchars($e->getMessage()) . '</div>';
}
?>
